customCSS:
.t, .history { color: #859289; }
.join { color: #a7c080; }
.part, .quit { color: #859289; }
.kick, .error { color: #e67e80; }
.notice { color: #dbbc7f; }
.action { color: #d699b6; }
.mode, .nick, .topic, .server { color: #83c092; }
.highlight { color: #d3c6aa; background-color: #543a48; border-left: 3px solid #d699b6; padding-left: 8px; }
.reply { color: #859289; border-left: 2px solid #7fbbb3; padding-left: 6px; }
.oper { color: #2d353b; background-color: #dbbc7f; }
.reactions { color: #7fbbb3; background-color: #3d484d; }
.card { background-color: #3d484d; border-color: #859289; }
.card-title { color: #7fbbb3; }
.card-desc { color: #859289; }
.daychange { color: #859289; border-color: #3d484d; }
